export interface SearchResult {
  atcCode?: string;
  name?: string;
  description?: string;
  content?: any;
  section46?: string;
  [key: string]: any;
}

export interface SearchResponse {
  results: SearchResult[];
  total?: number;
  page?: number;
  pageSize?: number;
}

class ApiService {
  private baseUrl: string;
  private token: string;
  private datasetId: string;

  constructor(baseUrl: string = 'https://cleyrop.ansm-secnum.cleyrop.net/data-serve/api/v1', token: string = 'black_cake_348230', datasetId: string = '325a0803-600a-4de7-860f-19187a601777') {
    this.baseUrl = baseUrl;
    this.token = token;
    this.datasetId = datasetId;
  }

  async search(atcCode: string, page: number = 1, pageSize: number = 10): Promise<SearchResponse> {
    try {
      const headers: Record<string, string> = {};
      if (this.token) {
        headers['Token'] = this.token;
      }

      // Get the specific dataset content
      const response = await fetch(`${this.baseUrl}/datasets/${this.datasetId}`, {
        headers
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const dataset = await response.json();
      
      // Search within the dataset content for the ATC code
      const results = this.searchATCInDataset(dataset, atcCode);

      return {
        results,
        total: results.length,
        page,
        pageSize
      };
    } catch (error) {
      console.error('Search error:', error);
      throw error;
    }
  }

  private searchATCInDataset(dataset: any, atcCode: string): SearchResult[] {
    const results: SearchResult[] = [];
    const searchTerm = atcCode.toLowerCase();

    // Handle different dataset structures
    if (dataset.content) {
      if (Array.isArray(dataset.content)) {
        // If content is an array of items
        dataset.content.forEach((item: any) => {
          if (this.itemContainsATC(item, searchTerm)) {
            results.push({
              ...item,
              atcCode: item.atcCode || item.code || item.id,
              name: item.name || item.title || item.description,
              content: item
            });
          }
        });
      } else if (typeof dataset.content === 'object') {
        // If content is a single object, search through its properties
        const flatResults = this.searchObjectForATC(dataset.content, searchTerm);
        results.push(...flatResults);
      }
    }

    // Also search in metadata if available
    if (dataset.metadata) {
      const metadataResults = this.searchObjectForATC(dataset.metadata, searchTerm);
      results.push(...metadataResults);
    }

    return results;
  }

  private itemContainsATC(item: any, searchTerm: string): boolean {
    const searchableFields = ['atcCode', 'code', 'id', 'name', 'title', 'description', 'section46'];
    
    return searchableFields.some(field => {
      const value = item[field];
      return value && typeof value === 'string' && value.toLowerCase().includes(searchTerm);
    });
  }

  private searchObjectForATC(obj: any, searchTerm: string): SearchResult[] {
    const results: SearchResult[] = [];
    
    if (typeof obj !== 'object' || obj === null) {
      return results;
    }

    Object.keys(obj).forEach(key => {
      const value = obj[key];
      
      if (typeof value === 'string' && value.toLowerCase().includes(searchTerm)) {
        results.push({
          atcCode: key,
          name: key,
          content: value,
          section46: value
        });
      } else if (typeof value === 'object' && value !== null) {
        // Recursively search nested objects
        const nestedResults = this.searchObjectForATC(value, searchTerm);
        results.push(...nestedResults);
      }
    });

    return results;
  }

  async getDatasetContent(): Promise<any> {
    try {
      const headers: Record<string, string> = {};
      if (this.token) {
        headers['TOKEN'] = this.token;
      }

      const response = await fetch(`${this.baseUrl}/datasets/${this.datasetId}`, {
        headers
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('Get dataset content error:', error);
      throw error;
    }
  }

  async getStructuredDataset(): Promise<any> {
    try {
      const headers: Record<string, string> = {};
      if (this.token) {
        headers['TOKEN'] = this.token;
      }

      const response = await fetch(`${this.baseUrl}/datasets/structured/${this.datasetId}`, {
        headers
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('Get structured dataset error:', error);
      throw error;
    }
  }

  setBaseUrl(url: string) {
    this.baseUrl = url;
  }

  setToken(token: string) {
    this.token = token;
  }

  setDatasetId(datasetId: string) {
    this.datasetId = datasetId;
  }
}

export const apiService = new ApiService();
